1	//! Single source of truth for every settable config key across
2	//! vc-x1's two config homes (the user config file and the
3	//! per-repo workspace config).
4	//!
5	//! - `crate::config_cmd` prints this registry as an annotated
6	//!   schema, and — with `--validate` — checks a config file's keys
7	//!   against it (dynamic-segment aware).
8	//! - `crate::init` derives init's commented defaults from
9	//!   `schema()`, so these surfaces cannot drift from this list.
10	
11	/// Which config home a key belongs to.
12	/// - `User` — `~/.config/vc-x1/config.toml`
13	/// - `WorkspaceCode` / `WorkspaceBot` — `<root>/.vc-config.toml`
14	///   in the work repo vs the `.claude` bot repo
15	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
16	pub enum Home {
17	    User,
18	    WorkspaceCode,
19	    WorkspaceBot,
20	}
21	
22	/// The value shape a key expects (for rendering / future typed
23	/// use).
24	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
25	pub enum ValueKind {
26	    Str,
27	    Usize,
28	    ItemList,
29	}
30	
31	/// One settable configuration key.
32	pub struct ConfigKey {
33	    /// The config key (TOML table and key joined by `.`), e.g.
34	    /// `"bot-session.col-width"`.
35	    pub path: &'static str,
36	    /// Which home(s) accept this key.
37	    pub homes: &'static [Home],
38	    /// The value shape this key expects.
39	    pub kind: ValueKind,
40	    /// Rendered default, `None` if there is no default.
41	    pub default: Option<&'static str>,
42	    /// Active (not commented) in init; the value is role-specific.
43	    pub required: bool,
44	    /// The path has a `<placeholder>` segment matching a family
45	    /// of keys (e.g. `repo.category.<cat>`).
46	    pub dynamic: bool,
47	    /// One-line description.
48	    pub doc: &'static str,
49	    /// The command/flag or structural context this key is
50	    /// associated with (e.g. `"bot-session --col-width"`).
51	    pub used_by: &'static str,
52	    /// A representative example value for keys with no default;
53	    /// rendered on the assignment line, marked `# example`,
54	    /// instead of a bare placeholder. `None` when the key has a
55	    /// real default (the default serves as the example).
56	    pub example: Option<&'static str>,
57	}
58	
59	/// Homes accepted by every `bot-session.*` key: all three homes,
60	/// since the user config and both workspace configs may each
61	/// carry a default.
62	const BOT_SESSION_HOMES: &[Home] = &[Home::User, Home::WorkspaceCode, Home::WorkspaceBot];
63	
64	/// Homes accepted by workspace-only keys (`repos.*`,
65	/// `push.*`): the two `.vc-config.toml` homes, never the user
66	/// config.
67	const WORKSPACE_HOMES: &[Home] = &[Home::WorkspaceCode, Home::WorkspaceBot];
68	
69	/// The complete registry of settable keys.
70	///
71	/// - User home: `default.*`, `repo.*`, and the per-account
72	///   `account.<name>.repo.*` family.
73	/// - `bot-session.*`: accepted in all three homes.
74	/// - Workspace-only: `repos.*`, `push.*`.
75	const SCHEMA: &[ConfigKey] = &[
76	    ConfigKey {
77	        path: "default.account",
78	        homes: &[Home::User],
79	        kind: ValueKind::Str,
80	        default: None,
81	        required: false,
82	        dynamic: false,
83	        doc: "Account profile (an [account.<name>] section) to use when --account is absent",
84	        used_by: "--account (init and account-aware commands)",
85	        example: Some("work"),
86	    },
87	    ConfigKey {
88	        path: "default.debug",
89	        homes: &[Home::User],
90	        kind: ValueKind::Str,
91	        default: None,
92	        required: false,
93	        dynamic: false,
94	        doc: "Default --debug value when used without an argument (reserved; not yet consumed)",
95	        used_by: "--debug (reserved; not yet consumed)",
96	        example: Some("true"),
97	    },
98	    ConfigKey {
99	        path: "repo.default",
100	        homes: &[Home::User],
101	        kind: ValueKind::Str,
102	        default: None,
103	        required: false,
104	        dynamic: false,
105	        doc: "Default repo category when --repo is bare — a [repo.category.<cat>] name: a built-in (remote, local) or your own",
106	        used_by: "--repo (default category when --repo is bare)",
107	        example: Some("acmehousing"),
108	    },
109	    ConfigKey {
110	        path: "repo.category.<cat>",
111	        homes: &[Home::User],
112	        kind: ValueKind::Str,
113	        default: None,
114	        required: false,
115	        dynamic: true,
116	        doc: "Literal value for repo category <cat> — a remote URL prefix (init appends /<NAME>.git) or a local parent dir",
117	        used_by: "--repo <cat> (init remote/local resolution)",
118	        example: Some("git@github.com:acmehousing"),
119	    },
120	    ConfigKey {
121	        path: "account.<name>.repo.default",
122	        homes: &[Home::User],
123	        kind: ValueKind::Str,
124	        default: None,
125	        required: false,
126	        dynamic: true,
127	        doc: "Per-account default repo category — a [repo.category.<cat>] name: a built-in (remote, local) or your own",
128	        used_by: "--account <name> with --repo",
129	        example: Some("acmehousing"),
130	    },
131	    ConfigKey {
132	        path: "account.<name>.repo.category.<cat>",
133	        homes: &[Home::User],
134	        kind: ValueKind::Str,
135	        default: None,
136	        required: false,
137	        dynamic: true,
138	        doc: "Per-account literal value for repo category <cat> (remote URL prefix or local parent dir)",
139	        used_by: "--account <name> with --repo <cat>",
140	        example: Some("git@github.com:acmehousing"),
141	    },
142	    ConfigKey {
143	        path: "bot-session.items",
144	        homes: BOT_SESSION_HOMES,
145	        kind: ValueKind::ItemList,
146	        default: Some("headers,user,assistant,tool,summary"),
147	        required: false,
148	        dynamic: false,
149	        doc: "Default bot-session item set (comma-separated)",
150	        used_by: "bot-session --<item> / --no-<item> / --all / --none",
151	        example: None,
152	    },
153	    ConfigKey {
154	        path: "bot-session.result-lines",
155	        homes: BOT_SESSION_HOMES,
156	        kind: ValueKind::Usize,
157	        default: Some("10"),
158	        required: false,
159	        dynamic: false,
160	        doc: "Default --result-lines: max lines shown per tool result (0 = unlimited)",
161	        used_by: "bot-session --result-lines",
162	        example: None,
163	    },
164	    ConfigKey {
165	        path: "bot-session.col-width",
166	        homes: BOT_SESSION_HOMES,
167	        kind: ValueKind::Usize,
168	        default: Some("68"),
169	        required: false,
170	        dynamic: false,
171	        doc: "Default --col-width: first-column width in the field-inventory views",
172	        used_by: "bot-session --col-width",
173	        example: None,
174	    },
175	    ConfigKey {
176	        path: "repos.work",
177	        homes: WORKSPACE_HOMES,
178	        kind: ValueKind::Str,
179	        default: None,
180	        required: true,
181	        dynamic: false,
182	        doc: "The work repo's path, relative to this config file's directory (\".\" in the work repo, \"..\" in the bot repo); the entry resolving to the config's own directory names the side",
183	        used_by: "find_workspace_root, side detection (structural; written by init)",
184	        example: Some("."),
185	    },
186	    ConfigKey {
187	        path: "repos.bot",
188	        homes: WORKSPACE_HOMES,
189	        kind: ValueKind::Str,
190	        default: None,
191	        required: false,
192	        dynamic: false,
193	        doc: "The bot repo's path, relative to this config file's directory (e.g. \".claude\" in the work repo, \".\" in the bot repo); presence signals dual-repo mode",
194	        used_by: "default_scope, scope resolution, ochid prefixes (structural)",
195	        example: Some(".claude"),
196	    },
197	];
198	
199	/// Returns the complete registry of settable config keys.
200	pub fn schema() -> &'static [ConfigKey] {
201	    SCHEMA
202	}
203	
204	/// Split a config key on its last `.` into `(section, leaf)`.
205	///
206	/// A path with no `.` (none exist in the current schema) falls
207	/// back to an empty section so the key still renders under a
208	/// blank `[]` header rather than panicking.
209	pub fn section_and_leaf(path: &str) -> (&str, &str) {
210	    match path.rfind('.') {
211	        Some(idx) => (&path[..idx], &path[idx + 1..]),
212	        None => ("", path),
213	    }
214	}
215	
216	/// Format a raw value string per `kind`, the way a default or an
217	/// example is rendered on the assignment line: `Usize` bare,
218	/// `Str`/`ItemList` quoted.
219	fn format_value(kind: ValueKind, raw: &str) -> String {
220	    match kind {
221	        ValueKind::Usize => raw.to_string(),
222	        ValueKind::Str | ValueKind::ItemList => format!("{raw:?}"),
223	    }
224	}
225	
226	/// Render a key's value cell: the quoted/bare default, or an
227	/// angle-bracket placeholder by kind when there is no default —
228	/// except a required key with no default, which renders
229	/// `<required>` so it stands out.
230	pub fn render_value(key: &ConfigKey) -> String {
231	    match key.default {
232	        Some(d) => format_value(key.kind, d),
233	        None => {
234	            if key.required {
235	                "<required>".to_string()
236	            } else {
237	                match key.kind {
238	                    ValueKind::Str => "<str>".to_string(),
239	                    ValueKind::Usize => "<usize>".to_string(),
240	                    ValueKind::ItemList => "<items>".to_string(),
241	                }
242	            }
243	        }
244	    }
245	}
246	
247	/// Render a key's `default:` note: the quoted/bare default, or a
248	/// parenthetical explaining the absence — `(required; ...)` for a
249	/// required key with no default (role-specific, filled by init),
250	/// `(none)` otherwise.
251	fn render_default_note(key: &ConfigKey) -> String {
252	    match key.default {
253	        Some(d) => format_value(key.kind, d),
254	        None => {
255	            if key.required {
256	                "(required; role-specific — see init)".to_string()
257	            } else {
258	                "(none)".to_string()
259	            }
260	        }
261	    }
262	}
263	
264	/// Word-wrap `text` into `#`-prefixed lines, `first_prefix` on the
265	/// first line and `cont_prefix` on continuations, each kept to
266	/// `width` columns where possible (a single word longer than
267	/// `width` still gets its own line, unsplit).
268	fn wrap_hash_comment(text: &str, first_prefix: &str, cont_prefix: &str, width: usize) -> String {
269	    let mut lines: Vec<String> = Vec::new();
270	    let mut current = String::new();
271	    for word in text.split_whitespace() {
272	        let prefix_len = if lines.is_empty() {
273	            first_prefix.len()
274	        } else {
275	            cont_prefix.len()
276	        };
277	        let sep = usize::from(!current.is_empty());
278	        let tentative_len = prefix_len + current.len() + sep + word.len();
279	        if !current.is_empty() && tentative_len > width {
280	            lines.push(std::mem::take(&mut current));
281	        }
282	        if !current.is_empty() {
283	            current.push(' ');
284	        }
285	        current.push_str(word);
286	    }
287	    if !current.is_empty() {
288	        lines.push(current);
289	    }
290	    let mut out = String::new();
291	    for (i, l) in lines.iter().enumerate() {
292	        let prefix = if i == 0 { first_prefix } else { cont_prefix };
293	        out.push_str(prefix);
294	        out.push_str(l);
295	        out.push('\n');
296	    }
297	    out
298	}
299	
300	/// Render one key as a thorough, self-documenting doc-block:
301	/// - `# <path> — <doc>` (word-wrapped onto `#   ...`
302	///   continuations past ~72 cols),
303	/// - `#   used by: <used_by>`,
304	/// - `#   default: <rendered default, or a "(none)"/"(required...)"
305	///   note>`,
306	/// - the assignment line itself — uncommented for a `required` key
307	///   (init fills in the role-specific value), commented (`# `)
308	///   otherwise, with the rendered default, a `key.example` value
309	///   marked with a trailing `# example` when there is no default,
310	///   or (absent both) a kind placeholder (`<str>` etc.),
311	/// - a trailing blank line, so consecutive blocks read as
312	///   paragraph-separated entries.
313	///
314	/// Shared by `crate::config_cmd` (printed schema) and `crate::init`
315	/// (commented defaults in the generated `.vc-config.toml`) so the
316	/// two surfaces cannot drift from each other's wording.
317	pub fn render_key_block(key: &ConfigKey) -> String {
318	    let mut out = String::new();
319	    let header_text = format!("{} — {}", key.path, key.doc);
320	    out.push_str(&wrap_hash_comment(&header_text, "# ", "#   ", 72));
321	    out.push_str(&format!("#   used by: {}\n", key.used_by));
322	    out.push_str(&format!("#   default: {}\n", render_default_note(key)));
323	    let (_section, leaf) = section_and_leaf(key.path);
324	    let prefix = if key.required { "" } else { "# " };
325	    match key.example {
326	        Some(ex) => {
327	            let value = format_value(key.kind, ex);
328	            out.push_str(&format!("{prefix}{leaf} = {value}   # example\n"));
329	        }
330	        None => {
331	            let value = render_value(key);
332	            out.push_str(&format!("{prefix}{leaf} = {value}\n"));
333	        }
334	    }
335	    out.push('\n');
336	    out
337	}
338	
339	#[cfg(test)]
340	mod tests {
341	    use super::*;
342	
343	    /// Finds a schema entry by its config key.
344	    ///
345	    /// - Panics if not found: tests only, and a missing key is a
346	    ///   test bug worth failing loudly on.
347	    #[allow(clippy::unwrap_used, clippy::expect_used)]
348	    fn find(path: &str) -> &'static ConfigKey {
349	        schema()
350	            .iter()
351	            .find(|k| k.path == path)
352	            .unwrap_or_else(|| panic!("schema key {path:?} not found"))
353	    }
354	
355	    #[test]
356	    fn defaults_match_source_consts() {
357	        assert_eq!(
358	            find("bot-session.col-width").default,
359	            Some(crate::bot_session::COL_WIDTH.to_string()).as_deref()
360	        );
361	        assert_eq!(
362	            find("bot-session.result-lines").default,
363	            Some(crate::bot_session::RESULT_LINE_CAP.to_string()).as_deref()
364	        );
365	    }
366	
367	    #[test]
368	    fn paths_unique() {
369	        let mut paths: Vec<&str> = schema().iter().map(|k| k.path).collect();
370	        paths.sort_unstable();
371	        let mut deduped = paths.clone();
372	        deduped.dedup();
373	        assert_eq!(paths.len(), deduped.len(), "duplicate path(s) in schema()");
374	    }
375	
376	    #[test]
377	    fn homes_non_empty() {
378	        for key in schema() {
379	            assert!(!key.homes.is_empty(), "{} has no homes", key.path);
380	        }
381	    }
382	
383	    /// Every key must show a concrete value in the rendered
384	    /// schema: a real `default`, or an `example` — never both
385	    /// `None` (which would render a bare `<str>` placeholder).
386	    #[test]
387	    fn every_key_has_default_or_example() {
388	        for key in schema() {
389	            assert!(
390	                key.default.is_some() || key.example.is_some(),
391	                "{}: has neither a default nor an example",
392	                key.path
393	            );
394	        }
395	    }
396	
397	    #[test]
398	    fn dynamic_keys_have_placeholder() {
399	        for key in schema() {
400	            let has_placeholder = key.path.contains('<');
401	            assert_eq!(
402	                key.dynamic, has_placeholder,
403	                "{}: dynamic={} but placeholder-presence={}",
404	                key.path, key.dynamic, has_placeholder
405	            );
406	        }
407	    }
408	}
