        info!("  {}  {}", c.new_first_line, todo_helpers::change_tag(c));
    }

    info!("");
    let total = analysis.todo_count + analysis.bugs_count;
    let n = analysis.changes.len();
    if n == 0 {
        info!(
            "{total} {} checked ({} Todo, {} Bugs), all sequential",
            todo_helpers::entry_word(total),
            analysis.todo_count,
            analysis.bugs_count
        );
